alter table public.gmail_oauth_tokens add column if not exists mailbox_id uuid; alter table public.gmail_oauth_tokens add column if not exists google_account_email text; alter table public.gmail_oauth_tokens add column if not exists is_active boolean not null default true; update public.gmail_oauth_tokens got set mailbox_id = am.id from public.admin_mailboxes am where lower(am.mailbox_email)=lower(got.email) and am.mailbox_provider='gmail' and got.mailbox_id is null; update public.gmail_oauth_tokens set google_account_email = email where google_account_email is null; alter table public.gmail_oauth_tokens drop constraint if exists gmail_oauth_tokens_email_key; create unique index if not exists gmail_oauth_tokens_mailbox_google_key on public.gmail_oauth_tokens (mailbox_id, lower(google_account_email)); create index if not exists gmail_oauth_tokens_mailbox_idx on public.gmail_oauth_tokens (mailbox_id); create index if not exists gmail_oauth_tokens_google_account_idx on public.gmail_oauth_tokens (lower(google_account_email)); alter table public.gmail_oauth_tokens add constraint gmail_oauth_tokens_mailbox_fkey foreign key (mailbox_id) references public.admin_mailboxes(id) on delete cascade;
